import{z as i,x as A,o,c as d,q as s,j as l,D as a,d as n,s as r,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"正则化回归的计量解释","description":"","frontmatter":{"title":"正则化回归的计量解释","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/pm-regularized-econ.md","filePath":"econ/pm-regularized-econ.md","lastUpdated":1791063341000}'),p={name:"econ/pm-regularized-econ.md"};function m(h,e,c,u,D,b){const t=A("Mermaid");return o(),d("div",null,[e[2]||(e[2]=s('<h1 id="正则化回归的计量解释" tabindex="-1">正则化回归的计量解释 <a class="header-anchor" href="#正则化回归的计量解释" aria-label="Permalink to &quot;正则化回归的计量解释&quot;">​</a></h1><div class="epigraph"><p>同一个 Lasso 能做两件事：预测时偏差是免费的，推断时偏差是致命的——分不清这两件事，选出来的显著性只是选择过程的回声。</p><footer>—— 据 Leeb and Pötscher, Can One Estimate the Conditional Distribution of Post-Model-Selection Estimators?, Econometric Theory 2005；Belloni, Chernozhukov and Hansen, JEP 2014 整理</footer></div><p><a href="/econ/pm-sparse-methods">上一课</a>把高维预测器钉在稀疏假设与样本外验证上，并留下一句话：入选集合是随机对象，系数带收缩偏差。计量经济学家的诉求不止预测——要系数、要区间、要检验。缺口是：惩罚世界里的推断怎么做，以及什么情况下根本做不到。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两个陷阱。其一，挑选后的显著性：用同一份数据先选模型、再对入选变量做 OLS 的 t 检验，检验的分布已被挑选改变。Leeb–Pötscher 2005 的不可能性说得更狠：模型选择估计量无法被一致地估计——真实参数附近，估计量的分布随参数值移动，任何置信区间要么无限宽要么失覆盖。其二，规格搜索的多重性：扫 \\(\\lambda\\)、扫变量、扫子样本，挑显著的报告，名义 \\(\\alpha\\) 与族错误率脱钩，这接<a href="/econ/multiple-testing-econ">多重检验</a>的纪律：只展示显著规格等于隐瞒 \\(m\\)。</p><h3 id="罚的另一面-先验与收缩" tabindex="-1">罚的另一面：先验与收缩 <a class="header-anchor" href="#罚的另一面-先验与收缩" aria-label="Permalink to &quot;罚的另一面：先验与收缩&quot;">​</a></h3><p>贝叶斯读法把罚变成先验：ridge 是高斯先验下的后验众数，Lasso 是拉普拉斯先验；Zellner 的 g 先验把先验信息强度随样本量参数化，贝叶斯模型平均（BMA）给出另一条路——不选模型，把不确定性摊在模型族上。经典侧的先声是 James–Stein 1961：平方损失下收缩估计一致优于最大似然，维数三即生效——「往零收」在决策论上不是妥协，是可兑现的免费午餐。</p><p><span class="marginnote">术语翻译：收缩（shrinkage）就是把估出来的系数「往零拉一点」。代价是引入一点偏差，换来方差大降——像把话音调小换更少杂音：单个系数看着变小，整体预测却稳得多。James–Stein 证明这种「认怂」在平方损失下平均总是赚的，这是收缩合法性的源头。</span></p><h3 id="推断的正路-双选择与去偏" tabindex="-1">推断的正路：双选择与去偏 <a class="header-anchor" href="#推断的正路-双选择与去偏" aria-label="Permalink to &quot;推断的正路：双选择与去偏&quot;">​</a></h3><p>post-double selection（Belloni–Chernozhukov–Hansen 2014）：关心 \\(d\\) 对 \\(y\\) 的效应时，对 \\(d\\) 过一遍变量选择（防遗漏变量偏差），对 \\(y\\) 过一遍（防只预测 \\(y\\) 的变量带来的选择偏倚），两个入选集合并起来跑 OLS。两类偏差都被压到 \\(\\sqrt n\\) 之下，常规推断恢复。工具变量侧同理：用 Lasso 从高维候选里构造最优工具（Belloni–Chen–Chernozhukov–Hansen 2012）。另一路是对 Lasso 本身去偏：把压缩掉的偏差用一步修正加回去，得到近似正态的估计量。</p><p><span class="marginnote">直觉类比：post-double selection 像审两遍稿——一遍审 \\(d\\)（与处理变量相关的控制一个不能漏），一遍审 \\(y\\)（只预测结局的变量不能冒充相关）。两遍筛出的并集才是安全的控制池：只审一遍，另一类偏差就漏网。</span></p><p><span class="marginnote">有效自由度 \\(\\mathrm{df}(\\lambda)=\\mathrm{tr}(H_\\lambda)\\) 是收缩世界的「变量个数」：岭回归的 df 从 \\(p\\) 连续降到零，Lasso 的 df 约等于入选数。报告 df 而不是数变量，才能在不同罚之间对齐复杂度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流程先声明目标。预测目标：沿上一课流水线走，接受偏差，不解读系数。推断目标：三选一——post-double selection 之后 OLS；desparsified Lasso 的去偏得分；BMA 的模型平均后验。控制变量的候选池必须预先声明，选择过程（哪一步筛、用了什么 \\(\\lambda\\)）写进报告；显著性声明过多重检验校正。省略这一步，等于把规格搜索的幸运当成了发现。</p>',14)),(o(),l(B,null,{default:a(()=>[r(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20GOAL%7B%22%E7%9B%AE%E6%A0%87%E6%98%AF%E9%A2%84%E6%B5%8B%E8%BF%98%E6%98%AF%E6%8E%A8%E6%96%AD%3F%22%7D%0A%20%20GOAL%20--%3E%7C%22%E9%A2%84%E6%B5%8B%22%7C%20PRED%5B%22%E6%B2%BF%E4%B8%8A%E4%B8%80%E8%AF%BE%E6%B5%81%E6%B0%B4%E7%BA%BF%2C%20%E6%8E%A5%E5%8F%97%E5%81%8F%E5%B7%AE%22%5D%0A%20%20GOAL%20--%3E%7C%22%E6%8E%A8%E6%96%AD%22%7C%20INF%5B%22%E5%8F%8C%E9%80%89%E6%8B%A9%E6%88%96%E5%8E%BB%E5%81%8F%E5%BE%97%E5%88%86%22%5D%0A%20%20PRED%20--%3E%20EVAL%5B%22%E6%A0%B7%E6%9C%AC%E5%A4%96%E5%8D%8F%E8%AE%AE%E4%B8%8E%E7%BB%84%E5%90%88%E5%9F%BA%E7%BA%BF%22%5D%0A%20%20INF%20--%3E%20MT%5B%22%E5%A4%9A%E9%87%8D%E6%A3%80%E9%AA%8C%E6%A0%A1%E6%AD%A3%22%5D%0A%20%20MT%20--%3E%20REP%5B%22%E6%8A%A5%E5%91%8A%E9%80%89%E6%8B%A9%E8%BF%87%E7%A8%8B%E4%B8%8E%E5%80%99%E9%80%89%E6%B1%A0%22%5D%0A%20%20EVAL%20--%3E%20REP%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=E("p",null,"为什么双选择有效：遗漏与选择两类偏差都以与样本相关的速率进入估计量，\\(\\sqrt n\\) 收敛要求它们低于 \\(\\sqrt n\\)；两遍选择正是把它们按可证的界限压下去，剩下的误差进入常规渐近正态。为什么朴素 post-selection 崩：入选集合是随机的，条件在「选中了这些变量」上做推断，等于把选择事件当成已知事实，t 统计量的零分布随之变形；Leeb–Pötscher 的不可能性说明这不是实现细节，是数学边界。df 的直觉同源：每个被收缩的系数贡献一份小于一的「自由度份额」，复杂度的账要按罚后的实际自由度记。",-1)),e[5]||(e[5]=E("p",null,"朴素 post-selection 与双选择在推断上的分岔：",-1)),(o(),l(B,null,{default:a(()=>[r(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%85%88%E9%80%89%E6%A8%A1%E5%9E%8B%EF%BC%8C%E5%86%8D%E7%94%A8%E5%90%8C%E4%B8%80%E4%BB%BD%E6%95%B0%E6%8D%AE%E5%81%9A%20t%20%E6%A3%80%E9%AA%8C%22%5D%20--%3E%20B%5B%22%E5%85%A5%E9%80%89%E9%9B%86%E5%90%88%E6%98%AF%E9%9A%8F%E6%9C%BA%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%8A%8A%E9%80%89%E6%8B%A9%E4%BA%8B%E4%BB%B6%E5%BD%93%E6%88%90%E5%B7%B2%E7%9F%A5%E4%BA%8B%E5%AE%9E%22%5D%0A%20%20C%20--%3E%20D%5B%22t%20%E7%BB%9F%E8%AE%A1%E9%87%8F%E7%9A%84%E9%9B%B6%E5%88%86%E5%B8%83%E5%8F%98%E5%BD%A2%EF%BC%9A%E6%98%BE%E8%91%97%E6%98%AF%E5%9B%9E%E5%A3%B0%22%5D%0A%20%20E%5B%22%E5%8F%8C%E9%80%89%E6%8B%A9%EF%BC%9Ad%20%E8%BF%87%E4%B8%80%E9%81%8D%E5%8A%A0%20y%20%E8%BF%87%E4%B8%80%E9%81%8D%22%5D%20--%3E%20F%5B%22%E5%90%88%E5%B9%B6%E5%85%A5%E9%80%89%E9%9B%86%E5%86%8D%E8%B7%91%20OLS%22%5D%0A%20%20F%20--%3E%20G%5B%22%E4%B8%A4%E7%B1%BB%E5%81%8F%E5%B7%AE%E5%8E%8B%E5%88%B0%20%E2%88%9An%20%E4%B9%8B%E4%B8%8B%22%5D%0A%20%20G%20--%3E%20H%5B%22%E5%B8%B8%E8%A7%84%E6%8E%A8%E6%96%AD%E6%81%A2%E5%A4%8D%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>稀疏推断仍依赖稀疏假设：不稀疏时，去偏区间的宽度按真相发散——这恰是诚实的表现，说明数据不支持那些系数。弱工具不因 Lasso 消失，最优工具的构造仍要过弱工具诊断。BMA 的结论对先验敏感，敏感性要做而不是辩解。识别从不来自惩罚：正则化改变估计的方差与偏差，不改变外生性来源。这些工具箱如何整体进因果问题，下一课给地图。</p><p><span class="marginnote">常见误区：用 Lasso「选出重要变量」，再对这几个入选变量跑 OLS 报显著性——这不是推断，是选择过程的回声。正规做法是 post-double selection 或去偏得分，并且把候选池和选择过程本身写进报告。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>挑选后的 t 检验无效；Leeb–Pötscher：模型选择估计量不存在一致估计，这是边界不是技巧问题。</li><li>罚即先验：ridge 对高斯、Lasso 对拉普拉斯；BMA 把模型不确定性摊开而不是挑一个。</li><li>推断正路是 post-double selection 或去偏得分；控制池与选择过程必须预先声明并写进报告。</li><li>\\(\\mathrm{df}(\\lambda)\\) 是复杂度的统一账本，跨罚对齐复杂度用 df 不用变量个数。</li><li>出处：James and Stein 1961；Leeb and Pötscher, <em>Econometric Theory</em> 2005；Belloni, Chen, Chernozhukov and Hansen, <em>Econometrica</em> 2012；Belloni, Chernozhukov and Hansen, <em>JEP</em> 2014；Zellner 1986。</li></ul>',5))])}const F=i(p,[["render",m]]);export{C as __pageData,F as default};
